import { NextResponse } from 'next/server'

const DEFAULT_RETRY_S = 60

/**
 * What an RA route answers when RetroAchievements failed it. A rate limit stays
 * a 429, with when to come back, as the client does not retry a 4xx. RA says 401 for a
 * key it does not accept (revoked or regenerated by the person, who then has to
 * link again) — measured 2026-10-16, and for any username, so it says nothing
 * about the account. That is a 403 `ra-key-invalid`, which the client does not
 * retry; a 404 or 422 is RA not knowing what was asked (a game that does not exist),
 * a 404 here that is not retried either; anything else is RA being unavailable (503), which it does.
 */
export function raUnavailable(err: unknown): NextResponse {
  const { status, retryAfter } = (err ?? {}) as { status?: number; retryAfter?: number | null }
  if (status === 401 || status === 403) return NextResponse.json({ error: 'ra-key-invalid' }, { status: 403 })
  // Asking again will not fix a thing RA does not know (or cannot process): a 4xx, which the client does not retry.
  if (status === 404 || status === 422) return NextResponse.json({ error: 'not-found' }, { status: 404 })
  if (status === 429) {
    const seconds = retryAfter ? Math.ceil(retryAfter / 1000) : DEFAULT_RETRY_S
    return NextResponse.json({ error: 'rate-limited' }, { status: 429, headers: { 'Retry-After': String(seconds) } })
  }
  return NextResponse.json({ message: 'RA service unavailable' }, { status: 503 })
}
